  'landing.f2.text': 'ҒЖБМ мемлекеттік гранттары, NU, KAIST KISS, Hungaricum, Bocconi ISU, GKS, CSC, MEXT және АҚШ need-blind колледждері — сіздің бюджетіңізге сай бір іріктеуде.',
  'landing.f3.title': 'Жол картасы және тапсырмалар',
  'landing.f3.text': 'Негізгі күндер, мерзімі бақыланатын SAT/IELTS/ҰБТ тапсырмалары, құжаттарды жүктеу және жоспарды күнтізбеге экспорттау.',
  'landing.f4.title': 'Эссе гиді + AI шолуы',
  'landing.f4.text': 'Personal Statement қаңқасы, қателер чек-листі және қабылдау комиссиясы критерийлері бойынша эссені AI бағалауы.',
  'landing.f5.title': 'Мүмкіндіктер және дайындық',
  'landing.f5.text': 'Әр университетке түсу ықтималдығы, ал тест әлі тапсырылмаса — болжам және қажетті балға дайындық жоспары.',
  'landing.f6.title': 'Жаңалықтарды талдайтын AI-кеңесші',
  'landing.f6.text': 'Қазақ, ағылшын және орыс тілдерінде чат: мамандық, денсаулық және бюджет бойынша университет таңдау, университет жаңалықтары мен әлеуметтік желілерін талдау.',

